// Command generate_accept creates the checked-in, offline DEX acceptance corpus.
package main

import (
	"archive/zip"
	"bytes"
	"crypto/sha1"
	"crypto/sha256"
	"encoding/binary"
	"flag"
	"fmt"
	"hash/adler32"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

const (
	dexPublic      = 0x0001
	dexPrivate     = 0x0002
	dexStatic      = 0x0008
	dexConstructor = 0x10000
)

type proto struct {
	ret    string
	params []string
}

func (p proto) key() string { return p.ret + "(" + strings.Join(p.params, "") + ")" }

func (p proto) shorty() string {
	var out strings.Builder
	out.WriteByte(shortType(p.ret))
	for _, parameter := range p.params {
		out.WriteByte(shortType(parameter))
	}
	return out.String()
}

func shortType(descriptor string) byte {
	if descriptor[0] == 'L' || descriptor[0] == '[' {
		return 'L'
	}
	return descriptor[0]
}

type methodRef struct {
	owner string
	name  string
	proto proto
}

func (m methodRef) key() string { return m.owner + "." + m.name + m.proto.key() }

type fieldRef struct {
	owner string
	name  string
	type_ string
}

func (f fieldRef) key() string { return f.owner + "." + f.name + ":" + f.type_ }

type codeSpec struct {
	registers uint16
	ins       uint16
	outs      uint16
	build     func(indices) []uint16
}

type methodDef struct {
	ref   methodRef
	flags uint32
	code  codeSpec
}

type fieldDef struct {
	ref   fieldRef
	flags uint32
}

type classSpec struct {
	descriptor string
	super      string
	flags      uint32
	fields     []fieldDef
	direct     []methodDef
	virtual    []methodDef
	references []methodRef
}

type indices struct {
	types   map[string]uint16
	methods map[string]uint16
	fields  map[string]uint16
}

type builtMethod struct {
	methodDef
	index   uint32
	codeOff uint32
}

type mapItem struct {
	type_  uint16
	size   uint32
	offset uint32
}

func main() {
	out := flag.String("out", filepath.Join("dex2jar", "testdata", "accept"), "output directory")
	flag.Parse()
	if err := generate(*out); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func generate(out string) error {
	if err := os.MkdirAll(out, 0o755); err != nil {
		return err
	}
	raw, err := buildDEX(arithmeticClass())
	if err != nil {
		return err
	}
	arrayClone, err := buildDEX(arrayCloneClass())
	if err != nil {
		return err
	}
	primary, err := buildDEX(simpleClass("Laccept/apk/Primary;", 3))
	if err != nil {
		return err
	}
	secondary, err := buildDEX(simpleClass("Laccept/apk/Secondary;", 5))
	if err != nil {
		return err
	}
	apk, err := buildAPK(primary, secondary)
	if err != nil {
		return err
	}
	fixtures := []struct {
		name string
		data []byte
	}{
		{name: "arithmetic.dex", data: raw},
		{name: "array-clone.dex", data: arrayClone},
		{name: "multidex.apk", data: apk},
	}
	for _, fixture := range fixtures {
		if err := os.WriteFile(filepath.Join(out, fixture.name), fixture.data, 0o644); err != nil {
			return err
		}
	}
	readme := `# Native dex2jar acceptance corpus

These files are repository-authored DEX 035 fixtures generated by
` + "`go run ./dex2jar/testdata/generate_accept`" + `. The generator directly writes
DEX structures and uses only the Go standard library; no Android SDK, D8, network,
or external compiler is involved.

- ` + "`arithmetic.dex`" + ` defines ` + "`accept.Arithmetic`" + `. It has a real constructor,
  an instance integer field, static integer arithmetic and branching, object creation,
  virtual/static invokes, and a self-checking ` + "`main`" + ` method.
- ` + "`array-clone.dex`" + ` defines ` + "`accept.ArrayClone`" + ` and invokes the legal
  array-owned method reference ` + "`[I.clone()Ljava/lang/Object;`" + `.
- ` + "`multidex.apk`" + ` contains canonical ` + "`classes.dex`" + ` and ` + "`classes2.dex`" + ` entries
  defining the unique classes ` + "`accept.apk.Primary`" + ` and ` + "`accept.apk.Secondary`" + `. Its
  asset and resource placeholders are intentionally not DEX inputs.

All class annotation offsets and code debug-info offsets are zero. The DEX headers
contain standard SHA-1 signatures and Adler-32 checksums. ` + "`SHA256SUMS`" + ` pins the
checked-in binary corpus.
`
	if err := os.WriteFile(filepath.Join(out, "README.md"), []byte(readme), 0o644); err != nil {
		return err
	}
	var manifest strings.Builder
	for _, fixture := range fixtures {
		sum := sha256.Sum256(fixture.data)
		fmt.Fprintf(&manifest, "%x  %s\n", sum, fixture.name)
	}
	return os.WriteFile(filepath.Join(out, "SHA256SUMS"), []byte(manifest.String()), 0o644)
}

func arithmeticClass() classSpec {
	owner := "Laccept/Arithmetic;"
	void := proto{ret: "V"}
	voidInt := proto{ret: "V", params: []string{"I"}}
	intResult := proto{ret: "I"}
	intInt := proto{ret: "I", params: []string{"I"}}
	mainProto := proto{ret: "V", params: []string{"[Ljava/lang/String;"}}
	objectInit := methodRef{owner: "Ljava/lang/Object;", name: "<init>", proto: void}
	constructor := methodRef{owner: owner, name: "<init>", proto: voidInt}
	value := methodRef{owner: owner, name: "value", proto: intResult}
	choose := methodRef{owner: owner, name: "choose", proto: intInt}
	run := methodRef{owner: owner, name: "run", proto: intResult}
	mainMethod := methodRef{owner: owner, name: "main", proto: mainProto}
	field := fieldRef{owner: owner, name: "value", type_: "I"}

	return classSpec{
		descriptor: owner,
		super:      "Ljava/lang/Object;",
		flags:      dexPublic,
		fields:     []fieldDef{{ref: field, flags: dexPrivate}},
		references: []methodRef{objectInit},
		direct: []methodDef{
			{
				ref: constructor, flags: dexPublic | dexConstructor,
				code: codeSpec{registers: 2, ins: 2, outs: 1, build: func(i indices) []uint16 {
					return words(
						invoke(0x70, i.methods[objectInit.key()], 0),
						field22c(0x59, i.fields[field.key()], 1, 0),
						[]uint16{0x000e},
					)
				}},
			},
			{
				ref: choose, flags: dexPublic | dexStatic,
				code: codeSpec{registers: 3, ins: 1, build: func(indices) []uint16 {
					return []uint16{0x2012, 0x0190, 0x0002, 0x013d, 0x0006, 0x1012, 0x0190, 0x0001, 0x010f, 0xf112, 0x010f}
				}},
			},
			{
				ref: run, flags: dexPublic | dexStatic,
				code: codeSpec{registers: 3, outs: 2, build: func(i indices) []uint16 {
					return words(
						[]uint16{0x7112},
						type21c(0x22, i.types[owner], 0),
						invoke(0x70, i.methods[constructor.key()], 0, 1),
						invoke(0x6e, i.methods[value.key()], 0),
						[]uint16{0x020a, 0x020f},
					)
				}},
			},
			{
				ref: mainMethod, flags: dexPublic | dexStatic,
				code: codeSpec{registers: 4, ins: 1, outs: 1, build: func(i indices) []uint16 {
					return words(
						[]uint16{0x4012},
						invoke(0x71, i.methods[choose.key()], 0),
						[]uint16{0x010a, 0x7012, 0x0133, 0x000a},
						invoke(0x71, i.methods[run.key()]),
						[]uint16{0x010a, 0x7012, 0x0133, 0x0003, 0x000e, 0x0212, 0x0227},
					)
				}},
			},
		},
		virtual: []methodDef{{
			ref: value, flags: dexPublic,
			code: codeSpec{registers: 2, ins: 1, build: func(i indices) []uint16 {
				return words(field22c(0x52, i.fields[field.key()], 0, 1), []uint16{0x000f})
			}},
		}},
	}
}

func arrayCloneClass() classSpec {
	owner := "Laccept/ArrayClone;"
	objectResult := proto{ret: "Ljava/lang/Object;"}
	cloneArrayProto := proto{ret: "Ljava/lang/Object;", params: []string{"[I"}}
	arrayClone := methodRef{owner: "[I", name: "clone", proto: objectResult}
	cloneArray := methodRef{owner: owner, name: "cloneArray", proto: cloneArrayProto}
	return classSpec{
		descriptor: owner,
		super:      "Ljava/lang/Object;",
		flags:      dexPublic,
		references: []methodRef{arrayClone},
		direct: []methodDef{{
			ref: cloneArray, flags: dexPublic | dexStatic,
			code: codeSpec{registers: 2, ins: 1, outs: 1, build: func(i indices) []uint16 {
				return words(
					invoke(0x6e, i.methods[arrayClone.key()], 1),
					[]uint16{0x000c, 0x0011},
				)
			}},
		}},
	}
}

func simpleClass(owner string, expected uint16) classSpec {
	void := proto{ret: "V"}
	mainProto := proto{ret: "V", params: []string{"[Ljava/lang/String;"}}
	objectInit := methodRef{owner: "Ljava/lang/Object;", name: "<init>", proto: void}
	constructor := methodRef{owner: owner, name: "<init>", proto: void}
	mainMethod := methodRef{owner: owner, name: "main", proto: mainProto}
	return classSpec{
		descriptor: owner,
		super:      "Ljava/lang/Object;",
		flags:      dexPublic,
		references: []methodRef{objectInit},
		direct: []methodDef{
			{
				ref: constructor, flags: dexPublic | dexConstructor,
				code: codeSpec{registers: 1, ins: 1, outs: 1, build: func(i indices) []uint16 {
					return words(invoke(0x70, i.methods[objectInit.key()], 0), []uint16{0x000e})
				}},
			},
			{
				ref: mainMethod, flags: dexPublic | dexStatic,
				code: codeSpec{registers: 4, ins: 1, build: func(indices) []uint16 {
					constantV0 := expected<<12 | 0x0012
					constantV1 := expected<<12 | 0x0112
					return []uint16{constantV0, constantV1, 0x1033, 0x0003, 0x000e, 0x0212, 0x0227}
				}},
			},
		},
	}
}

func words(parts ...[]uint16) []uint16 {
	var out []uint16
	for _, part := range parts {
		out = append(out, part...)
	}
	return out
}

func invoke(opcode byte, method uint16, registers ...uint16) []uint16 {
	if len(registers) > 5 {
		panic("too many invoke registers")
	}
	var packed uint16
	for index := 0; index < len(registers) && index < 4; index++ {
		packed |= (registers[index] & 0xf) << (4 * index)
	}
	word := uint16(opcode) | uint16(len(registers))<<12
	if len(registers) == 5 {
		word |= (registers[4] & 0xf) << 8
	}
	return []uint16{word, method, packed}
}

func field22c(opcode byte, field, a, b uint16) []uint16 {
	return []uint16{uint16(opcode) | (a&0xf)<<8 | (b&0xf)<<12, field}
}

func type21c(opcode byte, typeIndex, register uint16) []uint16 {
	return []uint16{uint16(opcode) | register<<8, typeIndex}
}

func buildDEX(spec classSpec) ([]byte, error) {
	methods := append(append([]methodRef(nil), spec.references...), methodRefs(spec.direct)...)
	methods = append(methods, methodRefs(spec.virtual)...)
	methodByKey := make(map[string]methodRef)
	for _, method := range methods {
		methodByKey[method.key()] = method
	}
	methods = methods[:0]
	for _, method := range methodByKey {
		methods = append(methods, method)
	}

	protosByKey := make(map[string]proto)
	typesSet := map[string]bool{spec.descriptor: true, spec.super: true}
	stringsSet := make(map[string]bool)
	for _, method := range methods {
		protosByKey[method.proto.key()] = method.proto
		typesSet[method.owner] = true
		stringsSet[method.name] = true
	}
	for _, field := range spec.fields {
		typesSet[field.ref.owner] = true
		typesSet[field.ref.type_] = true
		stringsSet[field.ref.name] = true
	}
	for _, p := range protosByKey {
		typesSet[p.ret] = true
		stringsSet[p.shorty()] = true
		for _, parameter := range p.params {
			typesSet[parameter] = true
		}
	}
	for descriptor := range typesSet {
		stringsSet[descriptor] = true
	}

	stringsTable := sortedKeys(stringsSet)
	stringIndex := make(map[string]uint32, len(stringsTable))
	for index, value := range stringsTable {
		stringIndex[value] = uint32(index)
	}
	types := sortedKeys(typesSet)
	sort.Slice(types, func(i, j int) bool { return stringIndex[types[i]] < stringIndex[types[j]] })
	typeIndex := make(map[string]uint16, len(types))
	for index, descriptor := range types {
		typeIndex[descriptor] = uint16(index)
	}
	protos := make([]proto, 0, len(protosByKey))
	for _, p := range protosByKey {
		protos = append(protos, p)
	}
	sort.Slice(protos, func(i, j int) bool {
		if typeIndex[protos[i].ret] != typeIndex[protos[j].ret] {
			return typeIndex[protos[i].ret] < typeIndex[protos[j].ret]
		}
		return protos[i].key() < protos[j].key()
	})
	protoIndex := make(map[string]uint16, len(protos))
	for index, p := range protos {
		protoIndex[p.key()] = uint16(index)
	}
	sort.Slice(methods, func(i, j int) bool {
		if typeIndex[methods[i].owner] != typeIndex[methods[j].owner] {
			return typeIndex[methods[i].owner] < typeIndex[methods[j].owner]
		}
		if stringIndex[methods[i].name] != stringIndex[methods[j].name] {
			return stringIndex[methods[i].name] < stringIndex[methods[j].name]
		}
		return protoIndex[methods[i].proto.key()] < protoIndex[methods[j].proto.key()]
	})
	methodIndex := make(map[string]uint16, len(methods))
	for index, method := range methods {
		methodIndex[method.key()] = uint16(index)
	}
	fields := append([]fieldDef(nil), spec.fields...)
	sort.Slice(fields, func(i, j int) bool {
		left, right := fields[i].ref, fields[j].ref
		if typeIndex[left.owner] != typeIndex[right.owner] {
			return typeIndex[left.owner] < typeIndex[right.owner]
		}
		if stringIndex[left.name] != stringIndex[right.name] {
			return stringIndex[left.name] < stringIndex[right.name]
		}
		return typeIndex[left.type_] < typeIndex[right.type_]
	})
	fieldIndex := make(map[string]uint16, len(fields))
	for index, field := range fields {
		fieldIndex[field.ref.key()] = uint16(index)
	}
	idx := indices{types: typeIndex, methods: methodIndex, fields: fieldIndex}

	const headerSize = 0x70
	stringIDsOff := headerSize
	typeIDsOff := stringIDsOff + 4*len(stringsTable)
	protoIDsOff := typeIDsOff + 4*len(types)
	fieldIDsOff := protoIDsOff + 12*len(protos)
	methodIDsOff := fieldIDsOff + 8*len(fields)
	classDefsOff := methodIDsOff + 8*len(methods)
	dataOff := classDefsOff + 32
	data := make([]byte, dataOff)

	stringDataOff := uint32(len(data))
	for index, value := range stringsTable {
		putU32(data, stringIDsOff+index*4, uint32(len(data)))
		data = appendULEB(data, uint32(len(value)))
		data = append(data, value...)
		data = append(data, 0)
	}

	typeListCount := 0
	firstTypeListOff := uint32(0)
	protoParameterOff := make(map[string]uint32)
	for _, p := range protos {
		if len(p.params) == 0 {
			continue
		}
		data = align(data, 4)
		if firstTypeListOff == 0 {
			firstTypeListOff = uint32(len(data))
		}
		typeListCount++
		protoParameterOff[p.key()] = uint32(len(data))
		data = appendU32(data, uint32(len(p.params)))
		for _, parameter := range p.params {
			data = appendU16(data, typeIndex[parameter])
		}
		if len(p.params)%2 != 0 {
			data = appendU16(data, 0)
		}
	}

	direct := buildMethods(spec.direct, methodIndex)
	virtual := buildMethods(spec.virtual, methodIndex)
	allDefinitions := append(append([]builtMethod(nil), direct...), virtual...)
	firstCodeOff := uint32(0)
	for methodIndex := range allDefinitions {
		data = align(data, 4)
		if firstCodeOff == 0 {
			firstCodeOff = uint32(len(data))
		}
		allDefinitions[methodIndex].codeOff = uint32(len(data))
		code := allDefinitions[methodIndex].code
		instructions := code.build(idx)
		data = appendU16(data, code.registers)
		data = appendU16(data, code.ins)
		data = appendU16(data, code.outs)
		data = appendU16(data, 0)
		data = appendU32(data, 0)
		data = appendU32(data, uint32(len(instructions)))
		for _, instruction := range instructions {
			data = appendU16(data, instruction)
		}
	}
	copy(direct, allDefinitions[:len(direct)])
	copy(virtual, allDefinitions[len(direct):])

	classDataOff := uint32(len(data))
	data = appendULEB(data, 0)
	data = appendULEB(data, uint32(len(fields)))
	data = appendULEB(data, uint32(len(direct)))
	data = appendULEB(data, uint32(len(virtual)))
	var previous uint32
	for index, field := range fields {
		current := uint32(fieldIndex[field.ref.key()])
		if index == 0 {
			previous = 0
		}
		data = appendULEB(data, current-previous)
		data = appendULEB(data, field.flags)
		previous = current
	}
	data = appendEncodedMethods(data, direct)
	data = appendEncodedMethods(data, virtual)

	data = align(data, 4)
	mapOff := uint32(len(data))
	mapItems := []mapItem{{0x0000, 1, 0}}
	if len(stringsTable) != 0 {
		mapItems = append(mapItems, mapItem{0x0001, uint32(len(stringsTable)), uint32(stringIDsOff)})
	}
	if len(types) != 0 {
		mapItems = append(mapItems, mapItem{0x0002, uint32(len(types)), uint32(typeIDsOff)})
	}
	if len(protos) != 0 {
		mapItems = append(mapItems, mapItem{0x0003, uint32(len(protos)), uint32(protoIDsOff)})
	}
	if len(fields) != 0 {
		mapItems = append(mapItems, mapItem{0x0004, uint32(len(fields)), uint32(fieldIDsOff)})
	}
	mapItems = append(mapItems,
		mapItem{0x0005, uint32(len(methods)), uint32(methodIDsOff)},
		mapItem{0x0006, 1, uint32(classDefsOff)},
		mapItem{0x2002, uint32(len(stringsTable)), stringDataOff},
	)
	if typeListCount != 0 {
		mapItems = append(mapItems, mapItem{0x1001, uint32(typeListCount), firstTypeListOff})
	}
	if len(allDefinitions) != 0 {
		mapItems = append(mapItems, mapItem{0x2001, uint32(len(allDefinitions)), firstCodeOff})
	}
	mapItems = append(mapItems,
		mapItem{0x2000, 1, classDataOff},
		mapItem{0x1000, 1, mapOff},
	)
	sort.Slice(mapItems, func(i, j int) bool { return mapItems[i].offset < mapItems[j].offset })
	data = appendU32(data, uint32(len(mapItems)))
	for _, item := range mapItems {
		data = appendU16(data, item.type_)
		data = appendU16(data, 0)
		data = appendU32(data, item.size)
		data = appendU32(data, item.offset)
	}

	copy(data[:8], []byte("dex\n035\x00"))
	putU32(data, 32, uint32(len(data)))
	putU32(data, 36, headerSize)
	putU32(data, 40, 0x12345678)
	putU32(data, 52, mapOff)
	putU32(data, 56, uint32(len(stringsTable)))
	if len(stringsTable) != 0 {
		putU32(data, 60, uint32(stringIDsOff))
	}
	putU32(data, 64, uint32(len(types)))
	if len(types) != 0 {
		putU32(data, 68, uint32(typeIDsOff))
	}
	putU32(data, 72, uint32(len(protos)))
	if len(protos) != 0 {
		putU32(data, 76, uint32(protoIDsOff))
	}
	putU32(data, 80, uint32(len(fields)))
	if len(fields) != 0 {
		putU32(data, 84, uint32(fieldIDsOff))
	}
	putU32(data, 88, uint32(len(methods)))
	if len(methods) != 0 {
		putU32(data, 92, uint32(methodIDsOff))
	}
	putU32(data, 96, 1)
	putU32(data, 100, uint32(classDefsOff))
	putU32(data, 104, uint32(len(data)-dataOff))
	putU32(data, 108, uint32(dataOff))

	for index, descriptor := range types {
		putU32(data, typeIDsOff+index*4, stringIndex[descriptor])
	}
	for index, p := range protos {
		off := protoIDsOff + index*12
		putU32(data, off, stringIndex[p.shorty()])
		putU32(data, off+4, uint32(typeIndex[p.ret]))
		putU32(data, off+8, protoParameterOff[p.key()])
	}
	for index, field := range fields {
		off := fieldIDsOff + index*8
		putU16(data, off, typeIndex[field.ref.owner])
		putU16(data, off+2, typeIndex[field.ref.type_])
		putU32(data, off+4, stringIndex[field.ref.name])
	}
	for index, method := range methods {
		off := methodIDsOff + index*8
		putU16(data, off, typeIndex[method.owner])
		putU16(data, off+2, protoIndex[method.proto.key()])
		putU32(data, off+4, stringIndex[method.name])
	}
	putU32(data, classDefsOff, uint32(typeIndex[spec.descriptor]))
	putU32(data, classDefsOff+4, spec.flags)
	putU32(data, classDefsOff+8, uint32(typeIndex[spec.super]))
	putU32(data, classDefsOff+12, 0)
	putU32(data, classDefsOff+16, ^uint32(0))
	putU32(data, classDefsOff+20, 0)
	putU32(data, classDefsOff+24, classDataOff)
	putU32(data, classDefsOff+28, 0)

	signature := sha1.Sum(data[32:])
	copy(data[12:32], signature[:])
	putU32(data, 8, adler32.Checksum(data[12:]))
	return data, nil
}

func methodRefs(definitions []methodDef) []methodRef {
	out := make([]methodRef, len(definitions))
	for index, definition := range definitions {
		out[index] = definition.ref
	}
	return out
}

func buildMethods(definitions []methodDef, methodIndex map[string]uint16) []builtMethod {
	out := make([]builtMethod, len(definitions))
	for index, definition := range definitions {
		out[index] = builtMethod{methodDef: definition, index: uint32(methodIndex[definition.ref.key()])}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].index < out[j].index })
	return out
}

func appendEncodedMethods(data []byte, methods []builtMethod) []byte {
	var previous uint32
	for index, method := range methods {
		if index == 0 {
			previous = 0
		}
		data = appendULEB(data, method.index-previous)
		data = appendULEB(data, method.flags)
		data = appendULEB(data, method.codeOff)
		previous = method.index
	}
	return data
}

func buildAPK(primary, secondary []byte) ([]byte, error) {
	entries := []struct {
		name string
		data []byte
	}{
		{name: "AndroidManifest.xml", data: []byte("offline acceptance placeholder\n")},
		{name: "assets/ignored.dex", data: []byte("not a top-level canonical DEX entry\n")},
		{name: "classes.dex", data: primary},
		{name: "classes2.dex", data: secondary},
		{name: "res/raw/placeholder.txt", data: []byte("ignored resource\n")},
	}
	var out bytes.Buffer
	writer := zip.NewWriter(&out)
	timestamp := time.Date(1980, time.January, 1, 0, 0, 0, 0, time.UTC)
	for _, entry := range entries {
		header := &zip.FileHeader{Name: entry.name, Method: zip.Store}
		header.SetModTime(timestamp)
		header.SetMode(0o644)
		file, err := writer.CreateHeader(header)
		if err != nil {
			return nil, err
		}
		if _, err := file.Write(entry.data); err != nil {
			return nil, err
		}
	}
	if err := writer.Close(); err != nil {
		return nil, err
	}
	return out.Bytes(), nil
}

func sortedKeys(set map[string]bool) []string {
	out := make([]string, 0, len(set))
	for key := range set {
		out = append(out, key)
	}
	sort.Strings(out)
	return out
}

func align(data []byte, alignment int) []byte {
	for len(data)%alignment != 0 {
		data = append(data, 0)
	}
	return data
}

func appendULEB(data []byte, value uint32) []byte {
	for {
		current := byte(value & 0x7f)
		value >>= 7
		if value != 0 {
			current |= 0x80
		}
		data = append(data, current)
		if value == 0 {
			return data
		}
	}
}

func appendU16(data []byte, value uint16) []byte {
	var raw [2]byte
	binary.LittleEndian.PutUint16(raw[:], value)
	return append(data, raw[:]...)
}

func appendU32(data []byte, value uint32) []byte {
	var raw [4]byte
	binary.LittleEndian.PutUint32(raw[:], value)
	return append(data, raw[:]...)
}

func putU16(data []byte, offset int, value uint16) {
	binary.LittleEndian.PutUint16(data[offset:offset+2], value)
}

func putU32(data []byte, offset int, value uint32) {
	binary.LittleEndian.PutUint32(data[offset:offset+4], value)
}
